{
  "description": "The creature is a chimera shown in right profile walking to the right, with the overall body, fur, and posture of a brown bear but bearing the dorsal armor and forehead horn of a large beetle. Its body is covered in thick shaggy brown fur that is lighter on the muzzle and underbelly and darker on the lower legs, with a robust bear-like build on four legs. Covering its entire back from the base of the neck to the rump is a large, highly glossy dark reddish-brown beetle shell with a smooth domed section over the shoulders and a larger ridged oval section over the back. A single large curved glossy horn with two small inner points rises from the center of its forehead. The head is bear-like with a black nose and small dark eyes, and a small furry tail stub is visible at the rear beneath the shell.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like head with dense brown fur, a lighter tan muzzle, a large black nose at the tip, small dark brown eyes in side view, and fine whiskers on the muzzle",
      "where": "at the front of the body, facing to the right in profile"
    },
    {
      "part": "horns",
      "looks_like": "single large glossy dark reddish-brown curved horn with two small pointed tines on its inner curve and a small metallic-looking circular base where it meets the skin, smooth and shiny like beetle chitin",
      "where": "projecting upward and slightly backward from the center of the forehead between the eyes and ears"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded furry ears covered in dense brown fur, with slightly lighter inner edges",
      "where": "on top of the head behind the horn, one slightly in front of the other in profile"
    },
    {
      "part": "mane",
      "looks_like": "thick shaggy ruff of longer brown fur forming a dense collar around the neck and chest, slightly darker and more tousled than the body fur",
      "where": "around the neck and upper chest behind the head and in front of the shell"
    },
    {
      "part": "legs",
      "looks_like": "four thick muscular bear legs covered in long shaggy brown fur that is darker on the lower portions, with visible joints and bulk",
      "where": "two forelegs under the chest and shoulders, one extended forward, and two hind legs under the hips and belly supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four broad bear paws with dark blunt claws, rounded pads and dense fur to the toes, glossy claws visible on each toe",
      "where": "at the ends of each leg at ground level, three paws in contact with the ground and the right fore paw lifted slightly"
    },
    {
      "part": "tail",
      "looks_like": "small short stubby furry tail covered in brown fur, rounded at the tip",
      "where": "at the rear left end of the body, protruding slightly from beneath the rear edge of the shell"
    },
    {
      "part": "shell",
      "looks_like": "large glossy beetle exoskeleton in dark reddish-brown with longitudinal ridges and grooves on the rear portion, scattered small black pits, a highly reflective smooth domed front portion, a thin black outline and a serrated lower margin with a row of small oval breathing holes",
      "where": "covering the entire dorsal side from the back of the neck over the shoulders and back to the rump, sitting on top of the fur"
    },
    {
      "part": "plates",
      "looks_like": "two main glossy plates forming the shell: a smaller smooth shield-like pronotum over the shoulders and a larger elongated oval elytra with fine parallel striations over the back, separated by a narrow dark seam",
      "where": "the pronotum is directly behind the neck ruff, the elytra extends from mid-back to above the tail"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "rhinoceros beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
